fn solve(n: i8) -> i8 {
    // Compute the integer quotient and remainder of n ÷ 3.
    // Since n >= 1, n/3 is nonnegative and fits in i8.
    let q = n / 3;
    let r = n % 3;

    // If n is divisible by 3, return 2*q; otherwise 2*q + 1.
    if r == 0 {
        2 * q
    } else {
        2 * q + 1
    }
}

